var s = GameState.state
var b = s.units.U_BOYZ_K.models
var pos = [[1580.0,1300.0],[1632.0,1300.0],[1684.0,1300.0],[1606.0,1345.0],[1658.0,1345.0]]
for i in range(b.size()):
	if i < 5:
		b[i].position = {"x": pos[i][0], "y": pos[i][1]}
		b[i].alive = true
	else:
		b[i].alive = false
		b[i].current_wounds = 0
s.units.U_WEIRDBOY_J.models[0].position = {"x": 1722.0, "y": 1345.0}
var w = s.units.U_WITCHSEEKERS_C.models
w[0].position = {"x": 1606.0, "y": 1249.0}
w[1].position = {"x": 1658.0, "y": 1249.0}
tree.current_scene._recreate_unit_visuals()
return RulesEngine.is_unit_engaged("U_BOYZ_K", s)

var tm = tree.root.get_node_or_null("ToastManager")
if tm == null:
	return false
for t in tm.active_toasts:
	if t == null or not is_instance_valid(t):
		continue
	var stack = [t]
	while not stack.is_empty():
		var n = stack.pop_back()
		if n is Label and str(n.text).find("Ordered Retreat cannot move through enemy models") != -1:
			return true
		stack.append_array(n.get_children())
return false

var layer = tree.root.get_node("Main").get_node("BoardRoot/TokenLayer")
var n := 0
for c in layer.get_children():
	if c.has_meta("unit_id") and str(c.get_meta("unit_id")) in ["U_BOYZ_K", "U_WEIRDBOY_J"] and not c.is_queued_for_deletion():
		n += 1
var alive := 0
for uid in ["U_BOYZ_K", "U_WEIRDBOY_J"]:
	for m in GameState.state.units[uid].models:
		if m.alive:
			alive += 1
print("[ea08] tokens ", n, " alive ", alive)
return n == alive

var md = PhaseManager.get_current_phase_instance().active_moves.get("U_BOYZ_K", {})
var alive := 0
for uid in ["U_BOYZ_K", "U_WEIRDBOY_J"]:
	for m in GameState.state.units[uid].models:
		if m.alive:
			alive += 1
var staged: Array = md.get("staged_moves", [])
print("[ea08] staged ", staged.size(), " of ", alive)
return staged.size() == alive and alive > 0
